input.sparql:
SELECT ?occupancy_series_id ?occupancy_point_uri WHERE {
  ?zone a brick:Zone ;
         rdfs:label "Perimeter_mid_ZN_3" ;
         brick:hasPoint/brick:isTimeseries ?occupancy_point_uri .
  ?occupancy_point_uri a brick:Occupancy_Sensor ;
         ref:hasExternalReference/ref:hasTimeseriesId ?occupancy_series_id .
}
